func TestInvalidUTF8ReportedNameIsDeterministic(t *testing.T) {
	graph := map[string]*Lineage{
		"z\xff": {Dataset: "z\xff"},
		"a\xfe": {Dataset: "a\xfe"},
	}
	first, err := MarshalGraphFile(graph)
